B.cJz=new A.p("leftLabel",B.t,"Column shown on each left node.",B.f,null)
B.cV1=new A.p("rightTable",B.at,"Table whose rows list down the right.",B.f,null)
B.cWc=new A.p("rightLabel",B.t,"Column shown on each right node.",B.f,null)
B.cOW=new A.p("linkColumn",B.t,"Ref column on the left table \u2192 a right row (one edge each).",B.f,null)
B.cUZ=new A.p("linkTable",B.at,"Link table of edges (alternative to linkColumn).",B.f,null)
B.cGA=new A.p("fromColumn",B.t,"linkTable column \u2192 left row id.",B.f,null)
B.cNp=new A.p("toColumn",B.t,"linkTable column \u2192 right row id.",B.f,null)
B.d_8=new A.p("edgeLabel",B.t,"linkTable column drawn on the line.",B.f,null)
B.cZ9=new A.p("leftAction",B.U,"Row action when a left node is tapped.",B.f,null)
B.cTg=new A.p("rightAction",B.U,"Row action when a right node is tapped.",B.f,null)
B.cYS=new A.p("emptyText",B.D,"Shown when both sides are empty; may be a {lang: text} map.",B.f,null)
