B.cvR=new A.d2("mapdiagram","A two-sided mapping diagram: left-table rows and right-table rows in two columns, with connector lines linking them (from a ref column or a link table). Tapping a node fires its row action.",B.bpt,!1)
B.cHm=new A.p("fitOnLoad",B.W,"Default ON: on first load, if the drawn content is not fully visible at the origin view, the camera fits it (centered, zoom \u2264 1\xd7) \u2014 a small preview shows the drawing, not an empty grid corner. Set false to keep the raw origin view.",B.f,null)
B.cYj=new A.p("nodesTable",B.at,"Table holding the nodes.",B.f,null)
B.cWX=new A.p("edgesTable",B.at,"Table holding the edges.",B.f,null)
B.cLw=new A.p("labelColumn",B.t,"Column shown on each node.",B.f,null)
B.cWG=new A.p("xColumn",B.t,"Node x-position column (free layout).",B.f,null)
B.cO0=new A.p("yColumn",B.t,"Node y-position column (free layout).",B.f,null)
B.cV3=new A.p("fromColumn",B.t,"Edge source-node id column.",B.f,null)
B.cQI=new A.p("toColumn",B.t,"Edge target-node id column.",B.f,null)
B.cSh=new A.p("edgeLabelColumn",B.t,'Edge label column (defaults to "label" when unset) \u2014 drawn on the edge itself, distinct from `labelColumn` which labels each node.',B.f,null)
B.anj=new A.p("height",B.D,'Canvas height. Accepts a number (logical px), "fill" (the full available body height, scrolling/panning internally), or "<frac>fill" (e.g. "0.55fill").',B.f,null)
