B.cYf=new A.p("filter",B.U,"Optional node-local filter {column, value} or {column, in:[...]}.",B.f,null)
B.d_7=new A.p("pileOrder",B.U,"Pinned pile order (a list of pileColumn values; shown even if empty).",B.f,null)
