B.cUR=new A.p("cardWidth",B.ae,"Card width in logical px (default 64).",B.f,null)
B.cXq=new A.p("fan",B.ae,"Overlap fraction for stacked/fanned cards (default 0.18).",B.f,null)
B.cIX=new A.p("maxStack",B.ae,"Max cards drawn for a stacked pile; deeper piles show top N + a count (default 6). Hands (fan) and grids are never capped.",B.f,null)
B.cXn=new A.p("fontFamily",B.D,"Font for rank/court letters (suits are vector-drawn). Default: system.",B.f,null)
B.cZm=new A.p("onTap",B.U,"Card-tap action spec { fn, args }.",B.f,null)
