B.cvG=new A.d2("cardtable","A felt table of real playing-card faces, grouped into piles from a table of card rows (one row per card). Cards slide between piles and flip on faceUp changes; rules stay in the data functions.",B.bA4,!1)
B.cOq=new A.p("table",B.at,"Dice table (one row per die).",B.f,null)
B.cXa=new A.p("valueColumn",B.t,'Numeric face-value column (default "value").',B.f,null)
B.cTS=new A.p("heldColumn",B.t,"Optional bool column; held dice show a ring and do not tumble.",B.f,null)
B.cQG=new A.p("sides",B.ae,"Die sides, for the roll-through flash (default 6).",B.f,null)
B.cY8=new A.p("dieSize",B.ae,"Die edge in logical px (default 64).",B.f,null)
